{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "button",
      "type": "DropdownMenuButtonProps",
      "description": "Props for the trigger button (Button props except onClick). Mutually exclusive with `renderTrigger`.",
      "default": "{ label: 'Menu' }"
    },
    {
      "name": "renderTrigger",
      "type": "(props: DropdownMenuTriggerProps) => ReactNode",
      "description": "Render the control the menu hangs off — an IconButton, a chip, an avatar, a list row — instead of the built-in Button. Spread the given props onto it: they carry the press model (a mouse opens on press-down, a held finger opens with the finger down), the keyboard opens, the toggle click, and `aria-haspopup`/`aria-expanded`/`aria-controls`/`id`; the menu is then named by that control through `aria-labelledby`. Mutually exclusive with `button`."
    },
    {
      "name": "items",
      "type": "DropdownMenuOption[]",
      "description": "Array of menu entries. Each entry is one of: an action item `{label, onClick?, href?, target?, rel?, icon?, description?, endContent?, isDisabled?, variant?, hasCloseOnSelect?, id?}` (`href` makes the row a real link, so a modified click keeps the browser's meaning; variant `\"destructive\"` renders it in the error color; `endContent` holds trailing content such as a keyboard-shortcut hint; `id` is the row's stable React key, needed only when the array reorders or filters), a divider `{type: \"divider\"}`, or a section `{type: \"section\", title?, id?, items: [...action items]}`.",
      "required": true
    },
    {
      "name": "presentation",
      "type": "'popover' | 'bottom-sheet' | 'adaptive'",
      "description": "Presentation surface for data-driven items. 'popover' stays anchored, 'bottom-sheet' always renders the actions in a modal BottomSheet, and 'adaptive' uses a BottomSheet on compact coarse-pointer layouts while remaining anchored elsewhere. Compound children currently support popover only. Omitted, the menu is anchored, and under a finger, on every device, the finger that opened it picks a row only after moving 10 px. Pass 'popover' to keep the pointer behavior on every device, the settle rule included."
    },
    {
      "name": "isMenuOpen",
      "type": "boolean",
      "description": "Controlled open state for the menu. Mounting with true renders the menu open without moving focus into it; focus moves to the first item only when the menu opens after mount."
    },
    {
      "name": "onOpenChange",
      "type": "(isOpen: boolean) => void",
      "description": "Callback fired when the open state changes."
    },
    {
      "name": "menuWidth",
      "type": "number | string",
      "description": "Minimum width for the popover presentation. Length values may grow for content; intrinsic and CSS-wide keywords select the preferred inline size. Every form is capped to the available viewport space. Defaults to matching the trigger width up to that cap."
    },
    {
      "name": "menuMaxHeight",
      "type": "number",
      "description": "Maximum height in pixels for the popover presentation, for a menu that must fit its rows. Lifts the default 300px cap; the viewport still bounds it."
    },
    {
      "name": "header",
      "type": "ReactNode",
      "description": "Content above the rows and outside the menu itself — a filter field, a toggle. A menu holds only its rows, so a control that is not a row goes here or in `footer`, never among the rows. It keeps its own keys and presses. With a header or footer the popover is a modal dialog around the menu: Tab and Shift+Tab move through the header, the menu and the footer and wrap at either end, and Escape closes. The bottom sheet shows it above the actions."
    },
    {
      "name": "footer",
      "type": "ReactNode",
      "description": "Content below the rows and outside the menu itself — a \"Create\" button. Tab from the menu moves into it, and Tab past its last control wraps to the start of the dialog (see `header`). The bottom sheet shows it below the actions."
    },
    {
      "name": "placement",
      "type": "'above' | 'below' | 'start' | 'end'",
      "description": "Popover placement relative to the trigger. Ignored by the bottom-sheet presentation. Logical: start/end resolve against the menu's own inherited direction (RTL mirrors).",
      "default": "'below'"
    },
    {
      "name": "alignment",
      "type": "'start' | 'center' | 'end'",
      "description": "Popover alignment along the placement axis. Ignored by the bottom-sheet presentation. Logical: start/end follow the menu's own inherited direction (RTL mirrors).",
      "default": "'start'"
    },
    {
      "name": "onClick",
      "type": "() => void",
      "description": "Callback fired for accepted trigger activation. The trailing click from the same press that light-dismissed the menu is ignored."
    },
    {
      "name": "hasChevron",
      "type": "boolean",
      "description": "Whether to show a chevron icon on the trigger button. Set to false for icon-only triggers.",
      "default": "true"
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Compound-mode menu content: DropdownMenuItem, DropdownMenuDivider, DropdownMenuSubMenu (a flyout on a laptop, a drilled-in view with a Back row on a phone), and the selectable items. Mutually exclusive with `items`."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
